export function binarySearch(e,t,i){let u,n;i=i||ascending;let f=0,o=e.length,l=!1;for(;f<o;)u=f+(o-f>>1),n=+i(e[u],t),n<0?f=u+1:(o=u,l=!n);return l?f:~f}export function ascending(e,t){return e>t?1:e<t?-1:0}export function descending(e,t){return e<t?1:e>t?-1:0}export function linearFindNearest(e,t,i){if(e[0]<=t)return 0;const u=e.length;if(t<=e[u-1])return u-1;if(typeof i=="function"){for(let n=1;n<u;++n){const f=e[n];if(f===t)return n;if(f<t)return i(t,e[n-1],f)>0?n-1:n}return u-1}if(i>0){for(let n=1;n<u;++n)if(e[n]<t)return n-1;return u-1}if(i<0){for(let n=1;n<u;++n)if(e[n]<=t)return n;return u-1}for(let n=1;n<u;++n){if(e[n]==t)return n;if(e[n]<t)return e[n-1]-t<t-e[n]?n-1:n}return u-1}export function reverseSubArray(e,t,i){for(;t<i;){const u=e[t];e[t]=e[i],e[i]=u,++t,--i}}export function extend(e,t){const i=Array.isArray(t)?t:[t],u=i.length;for(let n=0;n<u;n++)e[e.length]=i[n]}export function remove(e,t){const i=e.indexOf(t),u=i>-1;return u&&e.splice(i,1),u}export function equals(e,t){const i=e.length;if(i!==t.length)return!1;for(let u=0;u<i;u++)if(e[u]!==t[u])return!1;return!0}export function stableSort(e,t){const i=e.length,u=Array(e.length);let n;for(n=0;n<i;n++)u[n]={index:n,value:e[n]};for(u.sort(function(f,o){return t(f.value,o.value)||f.index-o.index}),n=0;n<e.length;n++)e[n]=u[n].value}export function isSorted(e,t,i){const u=t||ascending;return e.every(function(n,f){if(f===0)return!0;const o=u(e[f-1],n);return!(o>0||i&&o===0)})}
